ST.html:p:
IF FirstScan THEN
    LOOP_4750_03_TRIP        := TRUE;
    LOOP_4712_02_TRIP        := TRUE;
    LOOP_104_01_TRIP         := TRUE;
    SAFE_STATE               := TRUE;
    TV_4750_03_Out           := 6554;
    PVA_4712_02_Out          := 6554;
    XV_MNc_47124             := FALSE;
    SV_104_01_Out            := FALSE;
    HV_H_1007_N3_Out         := FALSE;
    HV_H_1007_N4_Out         := FALSE;
    HV_HS_4750_FC_Out        := FALSE;
    HV_73KH12_25_inlet_Out   := FALSE;
    HV_73KH12_25_outlet_Out  := FALSE;
    HV_73KH12_bypass_Out     := FALSE;
    HV_MNc_47126_block_Out   := FALSE;
    HV_Q_80_block_Out        := FALSE;
    TICSA_4750_03_HH_Latch(S1 := FALSE, R := TRUE);
    TICSA_4750_03_LL_Latch(S1 := FALSE, R := TRUE);
    PICSA_4712_02_HH_Latch(S1 := FALSE, R := TRUE);
    PICSA_4712_02_LL_Latch(S1 := FALSE, R := TRUE);
    PI_4712_01_HH_Latch(S1 := FALSE, R := TRUE);
    PI_4712_01_LL_Latch(S1 := FALSE, R := TRUE);
    FirstScan                := FALSE;
    RETURN;
END_IF;

TICSA_4750_03_Scaled := ((INT_TO_REAL(TICSA_4750_03_Raw) - 6554.0) / (32767.0 - 6554.0)) * 200.0;
PICSA_4712_02_Scaled := ((INT_TO_REAL(PICSA_4712_02_Raw) - 6554.0) / (32767.0 - 6554.0)) * 100.0;
PI_4712_01_Scaled    := ((INT_TO_REAL(PI_4712_01_Raw)    - 6554.0) / (32767.0 - 6554.0)) * 100.0;

TICSA_4750_03_HH := TICSA_4750_03_Scaled >= TICSA_4750_03_HH_SP;
TICSA_4750_03_LL := TICSA_4750_03_Scaled <= TICSA_4750_03_LL_SP;
PICSA_4712_02_HH := PICSA_4712_02_Scaled >= PICSA_4712_02_HH_SP;
PICSA_4712_02_LL := PICSA_4712_02_Scaled <= PICSA_4712_02_LL_SP;

IF TICSA_4750_03_HH OR TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := TRUE;
ELSIF LOOP_4750_03_TRIP AND MANUAL_RESET AND NOT TICSA_4750_03_HH AND NOT TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := FALSE;
END_IF;

IF PICSA_4712_02_HH OR PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := TRUE;
ELSIF LOOP_4712_02_TRIP AND MANUAL_RESET AND NOT PICSA_4712_02_HH AND NOT PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := FALSE;
END_IF;

IF SV_104_01_HH OR SV_104_01_LL THEN
    LOOP_104_01_TRIP := TRUE;
ELSIF LOOP_104_01_TRIP AND MANUAL_RESET AND NOT SV_104_01_HH AND NOT SV_104_01_LL THEN
    LOOP_104_01_TRIP := FALSE;
END_IF;

SAFE_STATE := ESTOP OR LOOP_4750_03_TRIP OR LOOP_4712_02_TRIP OR LOOP_104_01_TRIP;

IF NOT SAFE_STATE THEN
    TICSA_4750_03_Error    := TICSA_4750_03_SP - TICSA_4750_03_Scaled;
    TICSA_4750_03_Integral := TICSA_4750_03_Integral + (TICSA_4750_03_Ki * TICSA_4750_03_Error);
    IF TICSA_4750_03_Integral > 100.0 THEN
        TICSA_4750_03_Integral := 100.0;
    ELSIF TICSA_4750_03_Integral < 0.0 THEN
        TICSA_4750_03_Integral := 0.0;
    END_IF;
    TICSA_4750_03_Output_Pct := (TICSA_4750_03_Kp * TICSA_4750_03_Error) + TICSA_4750_03_Integral;
    IF TICSA_4750_03_Output_Pct > 100.0 THEN
        TICSA_4750_03_Output_Pct := 100.0;
    ELSIF TICSA_4750_03_Output_Pct < 0.0 THEN
        TICSA_4750_03_Output_Pct := 0.0;
    END_IF;
    TV_4750_03_Out := REAL_TO_INT(6554.0 + (TICSA_4750_03_Output_Pct / 100.0) * (32767.0 - 6554.0));
ELSE
    TV_4750_03_Out := 6554;
END_IF;

IF NOT SAFE_STATE THEN
    PICSA_4712_02_Error    := PICSA_4712_02_SP - PICSA_4712_02_Scaled;
    PICSA_4712_02_Integral := PICSA_4712_02_Integral + (PICSA_4712_02_Ki * PICSA_4712_02_Error);
    IF PICSA_4712_02_Integral > 100.0 THEN
        PICSA_4712_02_Integral := 100.0;
    ELSIF PICSA_4712_02_Integral < 0.0 THEN
        PICSA_4712_02_Integral := 0.0;
    END_IF;
    PICSA_4712_02_Output_Pct := (PICSA_4712_02_Kp * PICSA_4712_02_Error) + PICSA_4712_02_Integral;
    IF PICSA_4712_02_Output_Pct > 100.0 THEN
        PICSA_4712_02_Output_Pct := 100.0;
    ELSIF PICSA_4712_02_Output_Pct < 0.0 THEN
        PICSA_4712_02_Output_Pct := 0.0;
    END_IF;
    PVA_4712_02_Out := REAL_TO_INT(6554.0 + (PICSA_4712_02_Output_Pct / 100.0) * (32767.0 - 6554.0));
ELSE
    PVA_4712_02_Out := 6554;
END_IF;

IF NOT SAFE_STATE THEN
    XV_MNc_47124             := HS_4750_01;
    SV_104_01_Out            := TRUE;
    HV_H_1007_N3_Out         := TRUE;
    HV_H_1007_N4_Out         := TRUE;
    HV_HS_4750_FC_Out        := HS_4750_01;
    HV_73KH12_25_inlet_Out   := TRUE;
    HV_73KH12_25_outlet_Out  := TRUE;
    HV_73KH12_bypass_Out     := FALSE;
    HV_MNc_47126_block_Out   := TRUE;
    HV_Q_80_block_Out        := TRUE;
ELSE
    XV_MNc_47124             := FALSE;
    SV_104_01_Out            := FALSE;
    HV_H_1007_N3_Out         := FALSE;
    HV_H_1007_N4_Out         := FALSE;
    HV_HS_4750_FC_Out        := FALSE;
    HV_73KH12_25_inlet_Out   := FALSE;
    HV_73KH12_25_outlet_Out  := FALSE;
    HV_73KH12_bypass_Out     := FALSE;
    HV_MNc_47126_block_Out   := FALSE;
    HV_Q_80_block_Out        := FALSE;
END_IF;

IF TICSA_4750_03_Scaled >= TICSA_4750_03_HH_SP THEN
    TICSA_4750_03_HH_Set := TRUE;
ELSIF TICSA_4750_03_Scaled <= (TICSA_4750_03_HH_SP - TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_HH_Set := FALSE;
END_IF;
TICSA_4750_03_HH_Rst := TICSA_4750_03_HH_Ack AND NOT TICSA_4750_03_HH_Set;
TICSA_4750_03_HH_Latch(S1 := TICSA_4750_03_HH_Set, R := TICSA_4750_03_HH_Rst);

IF TICSA_4750_03_Scaled <= TICSA_4750_03_LL_SP THEN
    TICSA_4750_03_LL_Set := TRUE;
ELSIF TICSA_4750_03_Scaled >= (TICSA_4750_03_LL_SP + TICSA_4750_03_Deadband) THEN
    TICSA_4750_03_LL_Set := FALSE;
END_IF;
TICSA_4750_03_LL_Rst := TICSA_4750_03_LL_Ack AND NOT TICSA_4750_03_LL_Set;
TICSA_4750_03_LL_Latch(S1 := TICSA_4750_03_LL_Set, R := TICSA_4750_03_LL_Rst);

TICSA_4750_03_H := TICSA_4750_03_Scaled >= TICSA_4750_03_H_SP;
TICSA_4750_03_L := TICSA_4750_03_Scaled <= TICSA_4750_03_L_SP;

IF PICSA_4712_02_Scaled >= PICSA_4712_02_HH_SP THEN
    PICSA_4712_02_HH_Set := TRUE;
ELSIF PICSA_4712_02_Scaled <= (PICSA_4712_02_HH_SP - PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_HH_Set := FALSE;
END_IF;
PICSA_4712_02_HH_Rst := PICSA_4712_02_HH_Ack AND NOT PICSA_4712_02_HH_Set;
PICSA_4712_02_HH_Latch(S1 := PICSA_4712_02_HH_Set, R := PICSA_4712_02_HH_Rst);

IF PICSA_4712_02_Scaled <= PICSA_4712_02_LL_SP THEN
    PICSA_4712_02_LL_Set := TRUE;
ELSIF PICSA_4712_02_Scaled >= (PICSA_4712_02_LL_SP + PICSA_4712_02_Deadband) THEN
    PICSA_4712_02_LL_Set := FALSE;
END_IF;
PICSA_4712_02_LL_Rst := PICSA_4712_02_LL_Ack AND NOT PICSA_4712_02_LL_Set;
PICSA_4712_02_LL_Latch(S1 := PICSA_4712_02_LL_Set, R := PICSA_4712_02_LL_Rst);

PICSA_4712_02_H := PICSA_4712_02_Scaled >= PICSA_4712_02_H_SP;
PICSA_4712_02_L := PICSA_4712_02_Scaled <= PICSA_4712_02_L_SP;

IF PI_4712_01_Scaled >= PI_4712_01_HH_SP THEN
    PI_4712_01_HH_Set := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_HH_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_HH_Set := FALSE;
END_IF;
PI_4712_01_HH_Rst := PI_4712_01_HH_Ack AND NOT PI_4712_01_HH_Set;
PI_4712_01_HH_Latch(S1 := PI_4712_01_HH_Set, R := PI_4712_01_HH_Rst);

IF PI_4712_01_Scaled <= PI_4712_01_LL_SP THEN
    PI_4712_01_LL_Set := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_LL_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_LL_Set := FALSE;
END_IF;
PI_4712_01_LL_Rst := PI_4712_01_LL_Ack AND NOT PI_4712_01_LL_Set;
PI_4712_01_LL_Latch(S1 := PI_4712_01_LL_Set, R := PI_4712_01_LL_Rst);

PI_4712_01_H := PI_4712_01_Scaled >= PI_4712_01_H_SP;
PI_4712_01_L := PI_4712_01_Scaled <= PI_4712_01_L_SP;

System_Alarm :=
    TICSA_4750_03_HH_Latch.Q1 OR TICSA_4750_03_LL_Latch.Q1 OR
    TICSA_4750_03_H            OR TICSA_4750_03_L            OR
    PICSA_4712_02_HH_Latch.Q1 OR PICSA_4712_02_LL_Latch.Q1 OR
    PICSA_4712_02_H            OR PICSA_4712_02_L            OR
    PI_4712_01_HH_Latch.Q1    OR PI_4712_01_LL_Latch.Q1    OR
    PI_4712_01_H               OR PI_4712_01_L               OR
    SAFE_STATE;
